solution.solution.cpp:
#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

struct Access { std::uint32_t offset; std::uint32_t size; bool isFloat; bool isSigned; };

static std::string hex2(std::uint32_t v)
{
    static const char* const HEX{ "0123456789ABCDEF" };
    std::string out;
    do { out.insert(out.begin(), HEX[v & 0xF]); v >>= 4; } while (v);
    while (out.size() < 2) out.insert(out.begin(), '0');
    return out;
}

static std::string typeOf(const Access& a)
{
    if (a.isFloat && a.size == 4) return "float";
    if (a.isFloat && a.size == 8) return "double";
    return std::string(a.isSigned ? "std::int" : "std::uint") + std::to_string(a.size * 8) + "_t";
}

std::string recoverStruct(const std::string& name, std::vector<Access> accesses, std::uint32_t totalSize)
{
    std::stable_sort(accesses.begin(), accesses.end(), [](const Access& a, const Access& b) { return a.offset < b.offset; });
    std::vector<Access> fields;
    for (const Access& a : accesses)
    {
        if (!fields.empty() && fields.back().offset == a.offset)
        {
            Access& f{ fields.back() };
            f.size = std::max(f.size, a.size);
            f.isFloat = f.isFloat || a.isFloat;
            f.isSigned = f.isSigned || a.isSigned;
            continue;
        }
        if (!fields.empty() && a.offset < fields.back().offset + fields.back().size) continue;
        fields.push_back(a);
    }
    std::string out{ "struct " + name + "\n{\n" };
    std::uint32_t at{ 0 };
    for (const Access& f : fields)
    {
        if (f.offset > at) out += "    std::uint8_t pad_" + hex2(at) + "[" + std::to_string(f.offset - at) + "];\n";
        out += "    " + typeOf(f) + " field_" + hex2(f.offset) + ";\n";
        at = f.offset + f.size;
    }
    if (totalSize > at) out += "    std::uint8_t pad_" + hex2(at) + "[" + std::to_string(totalSize - at) + "];\n";
    return out + "};\n";
}

unitTests:
TEST("the lesson's example") {
    const std::string expected{
        "struct Player\n{\n"
        "    std::uint8_t pad_00[12];\n"
        "    std::int32_t field_0C;\n"
        "    float field_10;\n"
        "    float field_14;\n"
        "    std::uint8_t field_18;\n"
        "    std::uint8_t pad_19[7];\n"
        "    std::uint64_t field_20;\n"
        "};\n" };
    CHECK_EQ(recoverStruct("Player", { { 0x0C, 4, false, true }, { 0x10, 4, true, false }, { 0x14, 4, true, false }, { 0x18, 1, false, false }, { 0x20, 8, false, false } }, 0x28), expected);
}
TEST("order, merging and overlaps") {
    const std::string expected{
        "struct S\n{\n"
        "    std::int64_t field_00;\n"
        "    double field_08;\n"
        "    std::uint8_t pad_10[16];\n"
        "};\n" };
    CHECK_EQ(recoverStruct("S", { { 0x08, 8, true, false }, { 0x00, 4, false, false }, { 0x00, 8, false, true }, { 0x04, 2, false, false } }, 0x20), expected);
}
TEST("big offsets and no padding") {
    CHECK_EQ(recoverStruct("T", { { 0x1A0, 2, false, false } }, 0x1A2),
             std::string("struct T\n{\n    std::uint8_t pad_00[416];\n    std::uint16_t field_1A0;\n};\n"));
    CHECK_EQ(recoverStruct("Empty", {}, 0), std::string("struct Empty\n{\n};\n"));
}

